@spec tuning_spec  src=tests/specs/tuning_spec.lua  loc=536  cases=38
@exercises tuning (tuning)
@surface   tuning.derive, tuning.stepToParts, tuning.midiToStep, tuning.scalaPitch, tuning.unrooted, tuning.midiName, tuning.stepToMidi, tuning.parseScalaFile, tuning.parseScalaPitches, tuning.scalaToTemper, tuning.genEqual, tuning.edoDegrees, tuning.degreesToSpec, tuning.genHarmonics, tuning.genSubharmonics, tuning.parseChord, tuning.genChord, tuning.genCPS, tuning.genRank2, tuning.nextMosSize, tuning.mosInfo

# Intent
  Pins tuning.lua's pure display + derivation layer: the Option-B nameless
  step labels, the derived octaveStep / cellWidth fields, and the coordinate
  conversions between MIDI and step-octave. Realisation invariants (I1-I5)
  live in tm_tuning_spec; projection wiring in view_context_spec.

# Helpers
  @fn nameless(cents)  @ 10-12
  @fn stepText(temper, step, octave)  @ 16-19
      -- The two label parts joined, so a case that is about the whole label can
      -- assert it as one string.
  @fn rooted(root)  @ 22-28
      -- A 12EDO scale with the root fields the case is about; everything else default.

# Cases
  @case 'preset EDOs derive width 3 and a past-the-end octaveStep'  [pure]  @ 32-42
  @case 'named step renders name + octave'  [pure]  @ 46-51
  @case 'a negative octave renders as its magnitude and reports the sign'  [pure]  @ 55-64
  @case 'the octaveStep bump owns the sign: a step that crosses zero is not negative'  [pure]  @ 68-75
  @case 'nameless step falls back to degree-octave with a dash'  [pure]  @ 79-87
  @case 'nameless scale past 9 steps widens the cell for 2-digit degrees'  [pure]  @ 91-98
  @case 'sub-octave period widens the octave field for 2-digit octaves'  [pure]  @ 102-111
  @case 'a root numbering the octaves near zero narrows the field'  [pure]  @ 115-135
  @case 'a root numbering the range low makes the bottom end the wider'  [pure]  @ 139-151
  @case 'derive recomputes width when names are dropped'  [pure]  @ 155-163
  @case 'partially named scale: named steps keep their label, blanks fall back'  [pure]  @ 167-174
  @case 'scalaPitch parses ratios, cents, bare integers and n\\m steps'  [pure]  @ 178-192
  @case 'derive compiles pitches → cents and periodPitch → period'  [pure]  @ 196-204
  @case 'derive reduces an authored root to rootCents + octaveBase'  [pure]  @ 208-218
  @case 'a preset states no root and derives the default (0,0) = (1,-1)'  [pure]  @ 222-231
  @case 'unrooted is the library form: the four dropped, the stamps back at the default'  [pure]  @ 235-246
  @case 'midiName spells a pitch in the untempered twelve names'  [pure]  @ 250-256
  @case 'the default root reduces the conversions to MIDI-relative arithmetic'  [pure]  @ 260-275
  @case 'a flattened root moves every pitch by its offset and renames nothing'  [pure]  @ 279-301
  @case 'an octave-shifted root renames every octave and moves no pitch'  [pure]  @ 305-321
  @case 'the conversions invert each other at every root'  [pure]  @ 325-338
  @case 'EDO presets carry n\\m source tokens that derive back to their cents'  [pure]  @ 342-349
  @case 'parseScalaFile strips comments, description and count; returns pitch tokens'  [pure]  @ 353-361
  @case 'parseScalaPitches keeps every non-comment, non-blank line'  [pure]  @ 365-370
  @case 'scalaToTemper prepends the unison, splits the period, flags periodAsStep'  [pure]  @ 374-385
  @case 'scalaToTemper sorts unordered pitches ascending; widest becomes the period'  [pure]  @ 389-398
  @case 'scalaToTemper rejects an unparseable token'  [pure]  @ 402-407
  @case 'genEqual: full EDO and a diatonic subset, base implicit, period last'  [pure]  @ 411-423
  @case 'edoDegrees: relative cumulates, absolute sorts; non-octave equave suffixes'  [pure]  @ 427-435
  @case 'degreesToSpec round-trips edoDegrees in both modes'  [pure]  @ 439-443
  @case 'genHarmonics / genSubharmonics: rooted on the low harmonic, top is period'  [pure]  @ 447-456
  @case 'genChord: otonal vs inverted, last member is the period'  [pure]  @ 460-472
  @case 'parseChord rejects fewer than two notes or non-integers'  [pure]  @ 476-480
  @case 'genCPS: hexany rooted on the smallest product, 1/1 first, ascending'  [pure]  @ 484-490
  @case 'genRank2: pure-fifth size 7 / up 5 is Pythagorean major, 1/1 first'  [pure]  @ 494-500
  @case 'genRank2: size 4 / up 2 matches the Scale Workshop worked example'  [pure]  @ 504-509
  @case 'genRank2: irrational (EDO-step) generator emits cents tokens'  [pure]  @ 513-518
  @case 'nextMosSize / mosInfo: pure-fifth ladder 2->3->5->7->12; 7 is 5L 2s'  [pure]  @ 522-534

